with lines as (select id, created_at, key, value from carts lateral view explode(attributes) li as key, value) select date_trunc('day', created_at) as activity_day, count_if(key = 'utm_source') as utm_source_events, count(*) as num_rows, count(*) filter (where key = 'weight_kg') as weight_kg_rows, min(created_at) as first_created_at, count_if(key = 'weight_kg') as weight_kg_events from lines group by date_trunc('day', created_at) having count(*) filter (where key = 'weight_kg') > 1
